function NivelBadge({ nivel, tipologia }) {
  const color = NIVEL_COLOR[nivel] || '#8a8a82';
  return (
    <div style={{ display: 'inline-flex', flexDirection: 'column', gap: 2 }}>
      <span style={{ display: 'inline-block', width: 'fit-content', fontSize: 11, fontWeight: 500, padding: '2px 8px', borderRadius: 100, background: color + '22', color }}>{NIVEL_LABEL[nivel] || '—'}</span>
      {tipologia && <span style={{ fontSize: 11.5, color: '#6E7268' }}>{tipologia}</span>}
    </div>
  );
}

function buildCatalogTree(rows) {
  const tree = {};
  rows.forEach((r) => {
    if (!tree[r.tipo]) tree[r.tipo] = {};
    if (!tree[r.tipo][r.servicio]) tree[r.tipo][r.servicio] = {};
    if (!tree[r.tipo][r.servicio][r.prestacion]) tree[r.tipo][r.servicio][r.prestacion] = [];
    if (r.sub) tree[r.tipo][r.servicio][r.prestacion].push(r);
  });
  return tree;
}

function PrestacionesPicker({ value, onChange }) {
  const [query, setQuery] = useState('');
  const [openTipos, setOpenTipos] = useState({});
  const q = query.trim().toLowerCase();

  const filtered = q
    ? CATALOGO_PRESTACIONES.filter((r) => r.label.toLowerCase().includes(q))
    : CATALOGO_PRESTACIONES;

  const tree = buildCatalogTree(filtered);
  const tipos = Object.keys(tree);
  const isOpen = (t) => (q ? true : !!openTipos[t]);
  const toggleTipo = (t) => setOpenTipos((s) => ({ ...s, [t]: !s[t] }));

  const isChecked = (row) => value.includes(row.label);
  const toggle = (row) => {
    if (isChecked(row)) onChange(value.filter((v) => v !== row.label));
    else onChange([...value, row.label]);
  };

  const noSubItems = (prestKey, servicioObj) => servicioObj[prestKey].length === 0;
  const findRow = (tipo, servicio, prestacion, sub) => CATALOGO_PRESTACIONES.find((r) => r.tipo === tipo && r.servicio === servicio && r.prestacion === prestacion && r.sub === sub);

  return (
    <div>
      <input className="csh-input" style={{ marginBottom: 10 }} placeholder="Buscar prestación (ej. laboratorio, consulta externa, ecografía…)" value={query} onChange={(e) => setQuery(e.target.value)} />
      <div style={{ fontSize: 12, color: '#6E7268', marginBottom: 8 }}>{value.length} prestaciones seleccionadas</div>
      <div style={{ maxHeight: 380, overflowY: 'auto', border: '1px solid #DEDCD1', borderRadius: 8, background: '#fff' }}>
        {tipos.length === 0 && <div style={{ padding: 14, fontSize: 13, color: '#6E7268' }}>Sin resultados para "{query}".</div>}
        {tipos.map((tipo) => (
          <div key={tipo} style={{ borderBottom: '1px solid #E9E7DC' }}>
            <button type="button" onClick={() => toggleTipo(tipo)} style={{ width: '100%', textAlign: 'left', background: '#F5F3EA', border: 'none', padding: '9px 12px', fontSize: 12.5, fontWeight: 600, color: '#2A2E27', cursor: 'pointer', display: 'flex', justifyContent: 'space-between' }}>
              <span>{tipo}</span><span style={{ color: '#8B8F82' }}>{isOpen(tipo) ? '−' : '+'}</span>
            </button>
            {isOpen(tipo) && Object.keys(tree[tipo]).map((servicio) => (
              <div key={servicio} style={{ padding: '6px 12px 10px 16px' }}>
                <div style={{ fontSize: 12, fontWeight: 500, color: '#5B5F55', margin: '6px 0 4px' }}>{servicio}</div>
                {Object.keys(tree[tipo][servicio]).map((prestacion) => {
                  const subs = tree[tipo][servicio][prestacion];
                  if (subs.length === 0) {
                    const row = findRow(tipo, servicio, prestacion, '');
                    if (!row) return null;
                    return (
                      <label key={prestacion} style={{ display: 'flex', alignItems: 'center', gap: 7, fontSize: 13, padding: '3px 0', cursor: 'pointer' }}>
                        <input type="checkbox" checked={isChecked(row)} onChange={() => toggle(row)} />
                        <span>{prestacion}</span>
                      </label>
                    );
                  }
                  return (
                    <div key={prestacion} style={{ marginBottom: 4 }}>
                      <div style={{ fontSize: 12.5, color: '#3A3E35', margin: '4px 0 2px' }}>{prestacion}</div>
                      {subs.map((row) => (
                        <label key={row.id} style={{ display: 'flex', alignItems: 'center', gap: 7, fontSize: 13, padding: '3px 0 3px 14px', cursor: 'pointer' }}>
                          <input type="checkbox" checked={isChecked(row)} onChange={() => toggle(row)} />
                          <span>{row.sub}</span>
                        </label>
                      ))}
                    </div>
                  );
                })}
              </div>
            ))}
          </div>
        ))}
      </div>
    </div>
  );
}

export default function App() {
  const [session, setSession] = useState(null); // { role: 'admin' | 'hospital', unicodigo }
  const [loginUser, setLoginUser] = useState('');
  const [loginPass, setLoginPass] = useState('');
  const [loginError, setLoginError] = useState('');

  const [view, setView] = useState('panel');
  const [hospitales, setHospitales] = useState([]);
  const [loading, setLoading] = useState(true);
  const [form, setForm] = useState(emptyForm());
  const [toast, setToast] = useState('');
  const [search, setSearch] = useState('');
  const [filtroProvincia, setFiltroProvincia] = useState('');
  const [filtroNivel, setFiltroNivel] = useState('');
  const [filtroEstado, setFiltroEstado] = useState('');
  const [expandedId, setExpandedId] = useState(null);
  const [bulkPreview, setBulkPreview] = useState([]);
  const [bulkError, setBulkError] = useState('');
  const fileInputRef = useRef(null);
  const [users, setUsers] = useState([]);
  const [auditRows, setAuditRows] = useState([]);
  const [userForm, setUserForm] = useState({ username: '', password: '', role: 'hospital', unicodigo: '' });

  const showToast = (msg) => { setToast(msg); setTimeout(() => setToast(''), 2600); };

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const arr = await window.carteraApi.api('/api/hospitals');
      setHospitales(Array.isArray(arr) ? arr : []);
    } catch (e) {
      setHospitales([]);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    window.carteraApi.api('/api/auth/me').then((r) => {
      if (r.user) { setSession(r.user); load(); if (r.user.role === 'admin') loadSecurityData(); }
      else setLoading(false);
    }).catch(() => setLoading(false));
  }, [load]);

  const persist = async (arr) => {
    try {
      const current = session?.role === 'hospital' ? arr.find((h) => h.unicodigo === session.unicodigo) : null;
      if (session?.role === 'hospital' && current) {
        const saved = await window.carteraApi.api('/api/hospitals/' + encodeURIComponent(current.id), { method:'PUT', body: JSON.stringify(current) });
        setHospitales(arr.map(h => h.id === saved.id ? saved : h));
      } else if (session?.role === 'admin') {
        await window.carteraApi.api('/api/hospitals/bulk', { method:'POST', body: JSON.stringify({ hospitals: arr }) });
        await load();
      }
    } catch (e) { showToast(e.message || 'Error guardando los datos.'); }
  };

  const loadSecurityData = useCallback(async () => {
    try {
      const [u, a] = await Promise.all([
        window.carteraApi.api('/api/users'),
        window.carteraApi.api('/api/audit'),
      ]);
      setUsers(u); setAuditRows(a);
    } catch (e) {
      // Solo disponible para administradores.
    }
  }, []);

  const provisionHospitalUsers = async () => {
    try {
      const result = await window.carteraApi.api('/api/users/provision-hospitals', {
        method: 'POST', body: JSON.stringify({ hospitals: hospitales })
      });
      showToast(`${result.created} usuarios creados; ${result.existing} ya existían.`);
      await loadSecurityData();
    } catch (e) { showToast('No se pudieron crear los accesos.'); }
  };

  const createUser = async (e) => {
    e.preventDefault();
    try {
      await window.carteraApi.api('/api/users', { method: 'POST', body: JSON.stringify(userForm) });
      setUserForm({ username:'', password:'', role:'hospital', unicodigo:'' });
      showToast('Usuario creado.');
      await loadSecurityData();
    } catch (e) { showToast('No se pudo crear el usuario.'); }
  };

  const doLogin = async (e) => {
    e.preventDefault();
    const u = loginUser.trim();
    const p = loginPass.trim();
    try {
      const result = await window.carteraApi.api('/api/auth/login', { method: 'POST', body: JSON.stringify({ username: u, password: p }) });
      setSession(result.user);
      setLoginError('');
      await load();
      if (result.user.role === 'admin') await loadSecurityData();
    } catch (err) {
      setLoginError('Usuario o clave incorrectos.');
    }
  };

  const logout = async () => {
    try { await window.carteraApi.api('/api/auth/logout', { method: 'POST' }); } catch (e) {}
    setSession(null); setLoginUser(''); setLoginPass(''); setView('panel');
  };

  const resetForm = () => { setForm(emptyForm()); };

  const validate = () => {
    if (!form.nombreOficial.trim()) return 'Ingresa el nombre del establecimiento.';
    if (!form.provincia) return 'Selecciona la provincia.';
    if (!form.contactoNombre.trim()) return 'Ingresa un responsable de contacto.';
    if (form.servicios.length === 0) return 'Agrega al menos un servicio o especialidad.';
    return '';
  };

  const submitForm = async (e) => {
    e.preventDefault();
    const err = validate();
    if (err) { showToast(err); return; }
    const payload = { ...form, completado: form.servicios.length > 0, fechaActualizacion: new Date().toISOString().slice(0, 10) };
    try {
      if (form.id) {
        const saved = await window.carteraApi.api('/api/hospitals/' + encodeURIComponent(form.id), { method:'PUT', body: JSON.stringify(payload) });
        setHospitales(hospitales.map(h => h.id === saved.id ? saved : h));
        showToast('Registro actualizado.');
      } else {
        const saved = await window.carteraApi.api('/api/hospitals', { method:'POST', body: JSON.stringify(payload) });
        setHospitales([...hospitales, saved]);
        showToast('Hospital registrado.');
      }
      resetForm();
      setView('panel');
    } catch (e) { showToast(e.message || 'No se pudo guardar el establecimiento.'); }
  };

  const saveOwnProfile = async (record) => {
    const payload = { ...record, completado: record.servicios.length > 0, fechaActualizacion: new Date().toISOString().slice(0, 10) };
    try {
      const saved = await window.carteraApi.api('/api/hospitals/' + encodeURIComponent(record.id), { method:'PUT', body: JSON.stringify(payload) });
      setHospitales(hospitales.map(h => h.id === saved.id ? saved : h));
      showToast('Perfil actualizado.');
    } catch (e) { showToast(e.message || 'No se pudo actualizar el perfil.'); }
  };

  const editHospital = (h) => { setForm({ ...emptyForm(), ...h }); setView('form'); };
  const deleteHospital = async (id) => {
    try { await window.carteraApi.api('/api/hospitals/' + encodeURIComponent(id), { method:'DELETE' }); setHospitales(hospitales.filter((h) => h.id !== id)); showToast('Registro eliminado.'); }
    catch (e) { showToast(e.message || 'No se pudo eliminar el registro.'); }
  };

  const handleFile = (e) => {
    const file = e.target.files && e.target.files[0];
    if (!file) return;
    setBulkError('');
    const reader = new FileReader();
    reader.onload = (ev) => {
      try {
        const text = ev.target.result;
        const lines = String(text).split(/\r?\n/).filter((l) => l.trim().length > 0);
        if (lines.length < 2) { setBulkError('El archivo no tiene filas de datos.'); return; }
        const splitLine = (l) => l.split(',').map((c) => c.trim().replace(/^"|"$/g, ''));
        const headers = splitLine(lines[0]).map((h) => h.toLowerCase());
        const rows = lines.slice(1).map((l) => {
          const cells = splitLine(l);
          const obj = {};
          headers.forEach((h, i) => { obj[h] = cells[i] || ''; });
          return {
            id: genId(),
            unicodigo: obj['unicodigo'] || '',
            nombreOficial: obj['nombre'] || obj['nombreoficial'] || '',
            redAtencion: obj['red de atencion'] || '',
            institucion: obj['institucion'] || '',
            nivel: obj['nivel'] || '',
            nivelAtencionOficial: obj['nivel de atencion'] || '',
            tipologiaOficial: obj['tipologia'] || '',
            provincia: obj['provincia'] || '',
            canton: obj['ciudad'] || obj['canton'] || '',
            parroquia: obj['parroquia'] || '',
            zona: '', distrito: '', circuito: '',
            horarioAtencion: obj['horario'] || '',
            numeroCamas: obj['n° de camas'] || obj['numero de camas'] || obj['numero_camas'] || obj['camas'] || '',
            tipoCama: obj['tipo de cama'] || obj['tipo_cama'] || '',
            zonaFrontera: '', dificilAcceso: '',
            direccion: obj['direccion'] || '',
            contactoNombre: obj['contacto_nombre'] || obj['contacto'] || '',
            contactoCargo: obj['contacto_cargo'] || '',
            telefono: obj['telefono'] || '',
            email: obj['email'] || '',
            servicios: (obj['servicios'] || '').split(';').map((s) => s.trim()).filter(Boolean),
            observaciones: obj['observaciones'] || '',
            completado: false,
            fechaActualizacion: new Date().toISOString().slice(0, 10),
          };
        }).filter((r) => r.nombreOficial);
        if (rows.length === 0) { setBulkError('No se encontraron filas válidas (revisa la columna "nombre").'); return; }
        setBulkPreview(rows);
      } catch (err) { setBulkError('No se pudo leer el archivo. Verifica que sea un CSV separado por comas.'); }
    };
    reader.readAsText(file);
  };

  const confirmBulkImport = async () => {
    try {
      const result = await window.carteraApi.api('/api/hospitals/bulk', { method:'POST', body: JSON.stringify({ hospitals: bulkPreview }) });
      await load();
      showToast(`${result.created} creados, ${result.updated} actualizados.`);
      setBulkPreview([]);
      if (fileInputRef.current) fileInputRef.current.value = '';
      setView('panel');
    } catch (e) { showToast(e.message || 'No se pudo importar la información.'); }
  };

  const exportCSV = () => {
    const headers = ['unicodigo','nombre','provincia','canton','direccion','nivel','tipologia','contacto_nombre','contacto_cargo','telefono','email','servicios','observaciones','completado','fecha_actualizacion'];
    const rows = hospitales.map((h) => [
      h.unicodigo, h.nombreOficial, h.provincia, h.canton, h.direccion, h.nivel, h.tipologiaOficial,
      h.contactoNombre, h.contactoCargo, h.telefono, h.email, (h.servicios || []).join(';'), h.observaciones,
      h.completado ? 'Si' : 'No', h.fechaActualizacion || '',
    ].map((v) => `"${String(v || '').replace(/"/g, '""')}"`).join(','));
    const csv = [headers.join(','), ...rows].join('\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = 'cartera_servicios_hospitalarios.csv'; a.click();
    URL.revokeObjectURL(url);
  };

  const filtered = hospitales.filter((h) => {
    const q = search.trim().toLowerCase();
    const matchesQ = !q || h.nombreOficial.toLowerCase().includes(q) || (h.canton || '').toLowerCase().includes(q) || (h.unicodigo || '').includes(q) || (h.servicios || []).some((s) => s.toLowerCase().includes(q));
    const matchesProv = !filtroProvincia || h.provincia === filtroProvincia;
    const matchesNivel = !filtroNivel || h.nivel === filtroNivel;
    const matchesEstado = !filtroEstado || (filtroEstado === 'completo' ? h.completado : !h.completado);
    return matchesQ && matchesProv && matchesNivel && matchesEstado;
  });

  const nivelCounts = { I: 0, II: 0, III: 0, M: 0 };
  hospitales.forEach((h) => { if (nivelCounts[h.nivel] !== undefined) nivelCounts[h.nivel]++; });
  const completos = hospitales.filter((h) => h.completado).length;

  const provinciaCounts = {};
  hospitales.forEach((h) => { if (h.provincia) provinciaCounts[h.provincia] = (provinciaCounts[h.provincia] || 0) + 1; });
  const provinciaChart = Object.entries(provinciaCounts).sort((a, b) => b[1] - a[1]).slice(0, 8).map(([name, count]) => ({ name, count }));

  const servicioCounts = {};
  hospitales.forEach((h) => (h.servicios || []).forEach((s) => { servicioCounts[s] = (servicioCounts[s] || 0) + 1; }));
  const topServicios = Object.entries(servicioCounts).sort((a, b) => b[1] - a[1]).slice(0, 6);

  const styles = `
    @import url('https://fonts.googleapis.com/css2?family=Newsreader:ital,wght@0,400;0,500;0,600;1,400&family=IBM+Plex+Sans:wght@400;500;600&family=IBM+Plex+Mono:wght@400;500&display=swap');
    .csh-app { font-family: 'IBM Plex Sans', sans-serif; background: #EFEDE4; color: #22292B; min-height: 100vh; }
    .csh-app * { box-sizing: border-box; }
    .csh-header { background: #1B3A34; color: #F2F1E9; padding: 28px 32px 0; }
    .csh-header h1 { font-family: 'Newsreader', serif; font-weight: 500; font-size: 26px; margin: 0 0 4px; }
    .csh-header p { margin: 0 0 20px; color: #A9BEB6; font-size: 13px; }
    .csh-tabs { display: flex; gap: 2px; justify-content: space-between; align-items: flex-end; }
    .csh-tabs-left { display: flex; gap: 2px; }
    .csh-tab { padding: 10px 20px; border: none; background: rgba(255,255,255,0.06); color: #C7D4CE; font-family: 'IBM Plex Sans'; font-size: 13.5px; font-weight: 500; cursor: pointer; border-radius: 8px 8px 0 0; }
    .csh-tab.active { background: #EFEDE4; color: #1B3A34; }
    .csh-logout { background: none; border: none; color: #A9BEB6; font-size: 12.5px; cursor: pointer; padding: 10px 6px; }
    .csh-body { max-width: 1080px; margin: 0 auto; padding: 28px 24px 60px; }
    .csh-card { background: #FBFAF6; border: 1px solid #DEDCD1; border-radius: 10px; padding: 24px; }
    .csh-label { display: block; font-size: 12.5px; font-weight: 500; color: #5B5F55; margin: 0 0 6px; }
    .csh-input, .csh-select, .csh-textarea { width: 100%; padding: 9px 11px; border: 1px solid #CFCDC0; border-radius: 6px; background: #fff; font-family: 'IBM Plex Sans'; font-size: 14px; color: #22292B; }
    .csh-input:focus, .csh-select:focus, .csh-textarea:focus { outline: none; border-color: #1B3A34; box-shadow: 0 0 0 2px rgba(27,58,52,0.15); }
    .csh-input:disabled { background: #F0EEE3; color: #6E7268; }
    .csh-field { margin-bottom: 16px; }
    .csh-row { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
    .csh-btn { padding: 9px 18px; border-radius: 6px; border: 1px solid #1B3A34; background: #1B3A34; color: #fff; font-size: 13.5px; font-weight: 500; cursor: pointer; font-family: 'IBM Plex Sans'; }
    .csh-btn:hover { background: #152E29; }
    .csh-btn-ghost { background: transparent; color: #1B3A34; border: 1px solid #C6C4B8; }
    .csh-btn-ghost:hover { background: #F0EEE3; }
    .csh-chip { display: inline-flex; align-items: center; gap: 6px; background: #E4E9E1; color: #2A2E27; font-size: 12.5px; padding: 5px 10px; border-radius: 100px; margin: 0 6px 6px 0; }
    .csh-chip button { background: none; border: none; color: #6E7A6B; cursor: pointer; font-size: 13px; line-height: 1; padding: 0; }
    .csh-table { width: 100%; border-collapse: collapse; font-size: 13.5px; }
    .csh-table th { text-align: left; font-size: 11.5px; text-transform: uppercase; letter-spacing: 0.03em; color: #6E7268; padding: 8px 10px; border-bottom: 1px solid #DEDCD1; }
    .csh-table td { padding: 10px; border-bottom: 1px solid #E9E7DC; vertical-align: top; }
    .csh-table tr:hover td { background: #F5F3EA; }
    .csh-stat { background: #FBFAF6; border: 1px solid #DEDCD1; border-radius: 10px; padding: 16px 18px; }
    .csh-stat .n { font-family: 'Newsreader', serif; font-size: 28px; font-weight: 500; color: #1B3A34; }
    .csh-stat .l { font-size: 12px; color: #6E7268; margin-top: 2px; }
    .csh-toast { position: fixed; bottom: 24px; left: 50%; transform: translateX(-50%); background: #1B3A34; color: #fff; padding: 10px 18px; border-radius: 8px; font-size: 13.5px; z-index: 50; }
    .csh-login-wrap { min-height: 100vh; display: flex; align-items: center; justify-content: center; background: #1B3A34; }
    .csh-login-card { width: 340px; background: #FBFAF6; border-radius: 12px; padding: 32px 28px; }
    .csh-badge-estado { font-size: 11px; font-weight: 500; padding: 2px 8px; border-radius: 100px; }
  `;

  if (!session) {
    return (
      <div className="csh-app">
        <style>{styles}</style>
        <div className="csh-login-wrap">
          <form className="csh-login-card" onSubmit={doLogin}>
            <h1 style={{ fontFamily: 'Newsreader, serif', fontWeight: 500, fontSize: 21, margin: '0 0 4px', color: '#1B3A34' }}>Cartera de servicios hospitalarios</h1>
            <p style={{ fontSize: 12.5, color: '#6E7268', margin: '0 0 22px' }}>Ingresa con el unicódigo de tu establecimiento, o como administrador.</p>
            <div className="csh-field">
              <label className="csh-label">Usuario</label>
              <input className="csh-input" value={loginUser} onChange={(e) => setLoginUser(e.target.value)} placeholder="Unicódigo del establecimiento" autoFocus />
            </div>
            <div className="csh-field">
              <label className="csh-label">Contraseña</label>
              <input className="csh-input" type="password" value={loginPass} onChange={(e) => setLoginPass(e.target.value)} placeholder="Unicódigo del establecimiento" />
            </div>
            {loginError && <p style={{ color: '#A1443F', fontSize: 12.5, margin: '0 0 12px' }}>{loginError}</p>}
            <button type="submit" className="csh-btn" style={{ width: '100%' }}>Ingresar</button>
            {loading && <p style={{ fontSize: 11.5, color: '#A0A79B', marginTop: 14, textAlign: 'center' }}>Cargando base de establecimientos…</p>}
          </form>
        </div>
      </div>
    );
  }

  if (session.role === 'hospital') {
    const record = hospitales.find((h) => h.unicodigo === session.unicodigo) || null;
    const [local, setLocal] = [record, () => {}];
    return <HospitalProfile record={record} onSave={saveOwnProfile} onLogout={logout} styles={styles} toast={toast} showToast={showToast} loading={loading} />;
  }

  // Admin view
  return (
    <div className="csh-app">
      <style>{styles}</style>
      <div className="csh-header">
        <h1>Cartera de servicios hospitalarios</h1>
        <p>Panel administrador — registro consolidado por establecimiento de salud</p>
        <div className="csh-tabs">
          <div className="csh-tabs-left">
            {[['panel', 'Panel'], ['form', 'Registrar'], ['bulk', 'Carga masiva'], ['security', 'Seguridad']].map(([k, label]) => (
              <button key={k} className={'csh-tab' + (view === k ? ' active' : '')} onClick={() => { setView(k); if (k === 'form' && !form.id) resetForm(); }}>{label}</button>
            ))}
          </div>
          <button className="csh-logout" onClick={logout}>Cerrar sesión</button>
        </div>
      </div>

      <div className="csh-body">
        {loading ? (
          <p style={{ color: '#6E7268' }}>Cargando datos…</p>
        ) : view === 'security' ? (
          <div>
            <div className="csh-card" style={{ marginBottom: 18 }}>
              <h2 style={{ fontFamily: 'Newsreader, serif', fontWeight: 500, marginTop: 0 }}>Usuarios y accesos</h2>
              <p style={{ color:'#6E7268', fontSize:13 }}>Los establecimientos se identifican por su unicódigo. Para esta fase puedes provisionar accesos iniciales y posteriormente asignar contraseñas individuales.</p>
              <button className="csh-btn" onClick={provisionHospitalUsers}>Provisionar accesos de establecimientos</button>
            </div>
            <div className="csh-card" style={{ marginBottom: 18 }}>
              <h3 style={{ marginTop:0 }}>Crear usuario</h3>
              <form onSubmit={createUser} style={{ display:'grid', gridTemplateColumns:'1fr 1fr 1fr 1fr auto', gap:10, alignItems:'end' }}>
                <div><label className="csh-label">Usuario</label><input className="csh-input" value={userForm.username} onChange={e=>setUserForm({...userForm,username:e.target.value})} required /></div>
                <div><label className="csh-label">Contraseña</label><input className="csh-input" type="password" value={userForm.password} onChange={e=>setUserForm({...userForm,password:e.target.value})} required /></div>
                <div><label className="csh-label">Rol</label><select className="csh-select" value={userForm.role} onChange={e=>setUserForm({...userForm,role:e.target.value})}><option value="hospital">Establecimiento</option><option value="admin">Administrador</option></select></div>
                <div><label className="csh-label">Unicódigo</label><input className="csh-input" value={userForm.unicodigo} onChange={e=>setUserForm({...userForm,unicodigo:e.target.value})} /></div>
                <button className="csh-btn" type="submit">Crear</button>
              </form>
            </div>
            <div className="csh-card" style={{ marginBottom:18 }}>
              <h3 style={{ marginTop:0 }}>Usuarios registrados ({users.length})</h3>
              <table className="csh-table"><thead><tr><th>Usuario</th><th>Rol</th><th>Unicódigo</th><th>Estado</th></tr></thead><tbody>{users.map(u=><tr key={u.id}><td>{u.username}</td><td>{u.role}</td><td>{u.unicodigo || '—'}</td><td>{u.active ? 'Activo':'Inactivo'}</td></tr>)}</tbody></table>
            </div>
            <div className="csh-card">
              <h3 style={{ marginTop:0 }}>Auditoría reciente</h3>
              <table className="csh-table"><thead><tr><th>Fecha</th><th>Usuario</th><th>Acción</th><th>Entidad</th><th>Detalle</th></tr></thead><tbody>{auditRows.slice(0,100).map(a=><tr key={a.id}><td>{new Date(a.created_at).toLocaleString()}</td><td>{a.username}</td><td>{a.action}</td><td>{a.entity}</td><td>{a.details || '—'}</td></tr>)}</tbody></table>
            </div>
          </div>
        ) : view === 'panel' ? (
          <div>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(5, 1fr)', gap: 12, marginBottom: 20 }}>
              <div className="csh-stat"><div className="n">{hospitales.length}</div><div className="l">Establecimientos</div></div>
              <div className="csh-stat"><div className="n" style={{ color: '#1B3A34' }}>{completos}</div><div className="l">Perfiles completos</div></div>
              <div className="csh-stat"><div className="n" style={{ color: NIVEL_COLOR.I }}>{nivelCounts.I}</div><div className="l">Nivel I</div></div>
              <div className="csh-stat"><div className="n" style={{ color: NIVEL_COLOR.II }}>{nivelCounts.II}</div><div className="l">Nivel II</div></div>
              <div className="csh-stat"><div className="n" style={{ color: NIVEL_COLOR.III }}>{nivelCounts.III}</div><div className="l">Nivel III</div></div>
            </div>

            {hospitales.length > 0 && (
              <div className="csh-card" style={{ marginBottom: 20 }}>
                <div style={{ display: 'grid', gridTemplateColumns: '1.3fr 1fr', gap: 24 }}>
                  <div>
                    <div className="csh-label" style={{ marginBottom: 10 }}>Establecimientos por provincia</div>
                    <ResponsiveContainer width="100%" height={200}>
                      <BarChart data={provinciaChart} layout="vertical" margin={{ left: 8, right: 8 }}>
                        <CartesianGrid strokeDasharray="3 3" horizontal={false} stroke="#E4E2D6" />
                        <XAxis type="number" allowDecimals={false} tick={{ fontSize: 11, fill: '#6E7268' }} />
                        <YAxis type="category" dataKey="name" width={140} tick={{ fontSize: 11.5, fill: '#22292B' }} />
                        <Tooltip contentStyle={{ fontSize: 12, borderRadius: 6 }} />
                        <Bar dataKey="count" radius={[0, 4, 4, 0]}>
                          {provinciaChart.map((_, i) => <Cell key={i} fill="#6E8F72" />)}
                        </Bar>
                      </BarChart>
                    </ResponsiveContainer>
                  </div>
                  <div>
                    <div className="csh-label" style={{ marginBottom: 10 }}>Servicios más frecuentes reportados</div>
                    {topServicios.length === 0 ? <p style={{ fontSize: 13, color: '#6E7268' }}>Aún no se han reportado servicios.</p> : topServicios.map(([name, count]) => (
                      <div key={name} style={{ display: 'flex', justifyContent: 'space-between', fontSize: 13, padding: '6px 0', borderBottom: '1px solid #E9E7DC' }}>
                        <span>{name}</span><span style={{ fontFamily: 'IBM Plex Mono, monospace', color: '#6E7268' }}>{count}</span>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            )}

            <div style={{ display: 'flex', gap: 10, marginBottom: 14, flexWrap: 'wrap' }}>
              <input className="csh-input" style={{ maxWidth: 220 }} placeholder="Buscar por nombre, cantón, unicódigo…" value={search} onChange={(e) => setSearch(e.target.value)} />
              <select className="csh-select" style={{ maxWidth: 190 }} value={filtroProvincia} onChange={(e) => setFiltroProvincia(e.target.value)}>
                <option value="">Todas las provincias</option>
                {PROVINCIAS.map((p) => <option key={p} value={p}>{p}</option>)}
              </select>
              <select className="csh-select" style={{ maxWidth: 160 }} value={filtroNivel} onChange={(e) => setFiltroNivel(e.target.value)}>
                <option value="">Todos los niveles</option>
                <option value="I">Nivel I</option><option value="II">Nivel II</option><option value="III">Nivel III</option><option value="M">Móvil</option>
              </select>
              <select className="csh-select" style={{ maxWidth: 160 }} value={filtroEstado} onChange={(e) => setFiltroEstado(e.target.value)}>
                <option value="">Todos los estados</option>
                <option value="completo">Completos</option><option value="pendiente">Pendientes</option>
              </select>
              <div style={{ flex: 1 }} />
              <button className="csh-btn-ghost" onClick={exportCSV} disabled={hospitales.length === 0}>Exportar CSV</button>
            </div>

            {filtered.length === 0 ? (
              <div className="csh-card" style={{ textAlign: 'center', color: '#6E7268' }}>Ningún registro coincide con el filtro aplicado.</div>
            ) : (
              <div className="csh-card" style={{ padding: 0, overflow: 'hidden' }}>
                <table className="csh-table">
                  <thead>
                    <tr>
                      <th>Establecimiento</th><th>Unicódigo</th><th>Ubicación</th><th>Nivel / tipología</th><th>Estado</th><th></th>
                    </tr>
                  </thead>
                  <tbody>
                    {filtered.map((h) => (
                      <React.Fragment key={h.id}>
                        <tr>
                          <td style={{ fontWeight: 500 }}>{h.nombreOficial}</td>
                          <td style={{ fontFamily: 'IBM Plex Mono, monospace' }}>{h.unicodigo}</td>
                          <td>{h.canton}{h.canton && h.provincia ? ', ' : ''}{h.provincia}</td>
                          <td><NivelBadge nivel={h.nivel} tipologia={h.tipologiaOficial} /></td>
                          <td><span className="csh-badge-estado" style={{ background: h.completado ? '#E4E9E1' : '#F3E3C9', color: h.completado ? '#2E4A2F' : '#7A5A17' }}>{h.completado ? 'Completo' : 'Pendiente'}</span></td>
                          <td style={{ whiteSpace: 'nowrap' }}>
                            <button className="csh-btn-ghost" style={{ padding: '4px 10px', fontSize: 12, marginRight: 6 }} onClick={() => setExpandedId(expandedId === h.id ? null : h.id)}>{expandedId === h.id ? 'Cerrar' : 'Ver'}</button>
                            <button className="csh-btn-ghost" style={{ padding: '4px 10px', fontSize: 12, marginRight: 6 }} onClick={() => editHospital(h)}>Editar</button>
                            <button className="csh-btn-ghost" style={{ padding: '4px 10px', fontSize: 12, color: '#A1443F', borderColor: '#E3C6C4' }} onClick={() => deleteHospital(h.id)}>Eliminar</button>
                          </td>
                        </tr>
                        {expandedId === h.id && (
                          <tr>
                            <td colSpan={6} style={{ background: '#F5F3EA' }}>
                              <div style={{ padding: '8px 4px' }}>
                                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 16 }}>
                                  <div>
                                    <div className="csh-label">Acceso del establecimiento</div>
                                    <p style={{ margin: '0 0 10px', fontSize: 13.5 }}>Usuario y clave: <code style={{ fontFamily: 'IBM Plex Mono, monospace' }}>{h.unicodigo}</code></p>
                                    <div className="csh-label">Dirección</div>
                                    <p style={{ margin: '0 0 10px', fontSize: 13.5 }}>{h.direccion || '—'}</p>
                                    <div className="csh-label">Contacto</div>
                                    <p style={{ margin: '0 0 10px', fontSize: 13.5 }}>{h.contactoNombre || '—'} {h.contactoCargo ? `(${h.contactoCargo})` : ''}{h.telefono ? ` · ${h.telefono}` : ''}{h.email ? ` · ${h.email}` : ''}</p>
                                  </div>
                                  <div>
                                    <div className="csh-label">Zona / distrito / circuito</div>
                                    <p style={{ margin: '0 0 10px', fontSize: 13.5 }}>{h.zona} · {h.distrito} · {h.circuito}</p>
                                    <div className="csh-label">Horario</div>
                                    <p style={{ margin: '0 0 10px', fontSize: 13.5 }}>{h.horarioAtencion || '—'}</p>
                                  </div>
                                </div>
                                <div className="csh-label">Servicios / especialidades ({(h.servicios || []).length})</div>
                                <div style={{ margin: '4px 0 10px' }}>
                                  {(h.servicios || []).length === 0 ? <span style={{ fontSize: 13, color: '#6E7268' }}>Sin reportar aún.</span> : (h.servicios || []).map((s) => <span key={s} className="csh-chip">{s}</span>)}
                                </div>
                                {h.observaciones && (<><div className="csh-label">Observaciones</div><p style={{ margin: 0, fontSize: 13.5 }}>{h.observaciones}</p></>)}
                              </div>
                            </td>
                          </tr>
                        )}
                      </React.Fragment>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        ) : view === 'form' ? (
          <form className="csh-card" onSubmit={submitForm}>
            <h2 style={{ fontFamily: 'Newsreader, serif', fontWeight: 500, fontSize: 19, margin: '0 0 20px' }}>{form.id ? 'Editar establecimiento' : 'Registrar establecimiento adicional'}</h2>

            <div className="csh-row csh-field">
              <div>
                <label className="csh-label">Unicódigo (usuario/clave de acceso)</label>
                <input className="csh-input" value={form.unicodigo} onChange={(e) => setForm({ ...form, unicodigo: e.target.value.trim() })} placeholder="Ej. 9999" />
              </div>
              <div>
                <label className="csh-label">Nombre del establecimiento *</label>
                <input className="csh-input" value={form.nombreOficial} onChange={(e) => setForm({ ...form, nombreOficial: e.target.value })} />
              </div>
            </div>

            <div className="csh-row csh-field">
              <div>
                <label className="csh-label">Provincia *</label>
                <select className="csh-select" value={form.provincia} onChange={(e) => setForm({ ...form, provincia: e.target.value })}>
                  <option value="">Selecciona…</option>
                  {PROVINCIAS.map((p) => <option key={p} value={p}>{p}</option>)}
                </select>
              </div>
              <div>
                <label className="csh-label">Cantón</label>
                <input className="csh-input" value={form.canton} onChange={(e) => setForm({ ...form, canton: e.target.value })} />
              </div>
            </div>

            <div className="csh-field">
              <label className="csh-label">Dirección</label>
              <input className="csh-input" value={form.direccion} onChange={(e) => setForm({ ...form, direccion: e.target.value })} />
            </div>

            <div className="csh-row csh-field">
              <div>
                <label className="csh-label">Nivel de atención</label>
                <select className="csh-select" value={form.nivel} onChange={(e) => setForm({ ...form, nivel: e.target.value })}>
                  <option value="">Selecciona…</option>
                  <option value="I">Nivel I</option><option value="II">Nivel II</option><option value="III">Nivel III</option><option value="M">Móvil</option>
                </select>
              </div>
              <div>
                <label className="csh-label">Tipología</label>
                <input className="csh-input" value={form.tipologiaOficial} onChange={(e) => setForm({ ...form, tipologiaOficial: e.target.value })} placeholder="Ej. Hospital básico" />
              </div>
            </div>

            <div className="csh-row csh-field">
              <div>
                <label className="csh-label">N° de camas</label>
                <input className="csh-input" type="number" min="0" step="1" value={form.numeroCamas} onChange={(e) => setForm({ ...form, numeroCamas: e.target.value })} placeholder="Ej. 25" />
              </div>
              <div>
                <label className="csh-label">Tipo de cama</label>
                <select className="csh-select" value={form.tipoCama} onChange={(e) => setForm({ ...form, tipoCama: e.target.value })}>
                  <option value="">Selecciona…</option>
                  {TIPOS_CAMA.map((tipo) => <option key={tipo} value={tipo}>{tipo}</option>)}
                </select>
              </div>
            </div>

            <div className="csh-row csh-field">
              <div>
                <label className="csh-label">Responsable de contacto *</label>
                <input className="csh-input" value={form.contactoNombre} onChange={(e) => setForm({ ...form, contactoNombre: e.target.value })} />
              </div>
              <div>
                <label className="csh-label">Cargo</label>
                <input className="csh-input" value={form.contactoCargo} onChange={(e) => setForm({ ...form, contactoCargo: e.target.value })} />
              </div>
            </div>

            <div className="csh-row csh-field">
              <div>
                <label className="csh-label">Teléfono</label>
                <input className="csh-input" value={form.telefono} onChange={(e) => setForm({ ...form, telefono: e.target.value })} />
              </div>
              <div>
                <label className="csh-label">Correo electrónico</label>
                <input className="csh-input" type="email" value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} />
              </div>
            </div>

            <div className="csh-field">
              <label className="csh-label">Cartera de prestaciones ofrecidas *</label>
              <PrestacionesPicker value={form.servicios} onChange={(arr) => setForm({ ...form, servicios: arr })} />
            </div>

            <div className="csh-field">
              <label className="csh-label">Observaciones</label>
              <textarea className="csh-textarea" rows={3} value={form.observaciones} onChange={(e) => setForm({ ...form, observaciones: e.target.value })} />
            </div>

            <div style={{ display: 'flex', gap: 10, marginTop: 8 }}>
              <button type="submit" className="csh-btn">{form.id ? 'Guardar cambios' : 'Registrar establecimiento'}</button>
              <button type="button" className="csh-btn-ghost" onClick={() => { resetForm(); setView('panel'); }}>Cancelar</button>
            </div>
          </form>
        ) : (
          <div className="csh-card">
            <h2 style={{ fontFamily: 'Newsreader, serif', fontWeight: 500, fontSize: 19, margin: '0 0 8px' }}>Carga masiva</h2>
            <p style={{ fontSize: 13.5, color: '#6E7268', margin: '0 0 16px' }}>
              CSV con columnas: unicodigo, nombre, provincia, canton, direccion, nivel, tipologia, contacto_nombre, contacto_cargo, telefono, email, numero_camas, tipo_cama, servicios (separados por ; ), observaciones.
            </p>
            <input ref={fileInputRef} type="file" accept=".csv,.txt" onChange={handleFile} style={{ fontSize: 13.5 }} />
            {bulkError && <p style={{ color: '#A1443F', fontSize: 13, marginTop: 10 }}>{bulkError}</p>}

            {bulkPreview.length > 0 && (
              <div style={{ marginTop: 20 }}>
                <p style={{ fontSize: 13.5, fontWeight: 500 }}>{bulkPreview.length} registros listos para importar</p>
                <div style={{ maxHeight: 260, overflowY: 'auto', border: '1px solid #DEDCD1', borderRadius: 8 }}>
                  <table className="csh-table">
                    <thead><tr><th>Unicódigo</th><th>Nombre</th><th>Provincia</th><th>N° camas</th><th>Tipo de cama</th><th>Servicios</th></tr></thead>
                    <tbody>{bulkPreview.map((r) => (<tr key={r.id}><td>{r.unicodigo}</td><td>{r.nombreOficial}</td><td>{r.provincia}</td><td>{r.numeroCamas || '—'}</td><td>{r.tipoCama || '—'}</td><td>{r.servicios.length}</td></tr>))}</tbody>
                  </table>
                </div>
                <div style={{ display: 'flex', gap: 10, marginTop: 14 }}>
                  <button className="csh-btn" onClick={confirmBulkImport}>Importar {bulkPreview.length} registros</button>
                  <button className="csh-btn-ghost" onClick={() => { setBulkPreview([]); if (fileInputRef.current) fileInputRef.current.value = ''; }}>Descartar</button>
                </div>
              </div>
            )}
          </div>
        )}
      </div>

      {toast && <div className="csh-toast">{toast}</div>}
    </div>
  );
}

function HospitalProfile({ record, onSave, onLogout, styles, toast, showToast, loading }) {
  const [local, setLocal] = useState(record);
  const [sigcasSelection, setSigcasSelection] = useState(null);
  const [sigcasTab, setSigcasTab] = useState('catalogo');

  useEffect(() => { setLocal(record); }, [record]);

  if (loading) {
    return (
      <div className="csh-app"><style>{styles}</style>
        <div className="csh-body"><p style={{ color: '#6E7268' }}>Cargando perfil…</p></div>
      </div>
    );
  }

  if (!local) {
    return (
      <div className="csh-app"><style>{styles}</style>
        <div className="csh-header"><h1>Cartera de servicios hospitalarios</h1><div className="csh-tabs"><div /><button className="csh-logout" onClick={onLogout}>Cerrar sesión</button></div></div>
        <div className="csh-body"><p>No se encontró tu establecimiento. Contacta al administrador.</p></div>
      </div>
    );
  }

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!local.contactoNombre.trim()) { showToast('Ingresa un responsable de contacto.'); return; }
    if (local.servicios.length === 0) { showToast('Agrega al menos un servicio o especialidad.'); return; }
    onSave(local);
  };

  return (
    <div className="csh-app">
      <style>{styles}</style>
      <div className="csh-header">
        <h1>{local.nombreOficial}</h1>
        <p>Unicódigo {local.unicodigo} · {local.provincia}{local.canton ? `, ${local.canton}` : ''}</p>
        <div className="csh-tabs"><div /><button className="csh-logout" onClick={onLogout}>Cerrar sesión</button></div>
      </div>
      <div className="csh-body">
        <form className="csh-card" onSubmit={handleSubmit}>
          <h2 style={{ fontFamily: 'Newsreader, serif', fontWeight: 500, fontSize: 18, margin: '0 0 4px' }}>Datos oficiales</h2>
          <p style={{ fontSize: 12, color: '#6E7268', margin: '0 0 16px' }}>Estos campos provienen de la base institucional y no se pueden editar aquí.</p>
          <div className="csh-row csh-field">
            <div><label className="csh-label">Nivel de atención</label><input className="csh-input" value={NIVEL_LABEL[local.nivel] || local.nivelAtencionOficial} disabled /></div>
            <div><label className="csh-label">Tipología</label><input className="csh-input" value={local.tipologiaOficial} disabled /></div>
          </div>
          <div className="csh-row csh-field">
            <div><label className="csh-label">Zona / distrito / circuito</label><input className="csh-input" value={`${local.zona} · ${local.distrito} · ${local.circuito}`} disabled /></div>
            <div><label className="csh-label">Parroquia</label><input className="csh-input" value={local.parroquia} disabled /></div>
          </div>

          <h2 style={{ fontFamily: 'Newsreader, serif', fontWeight: 500, fontSize: 18, margin: '20px 0 16px' }}>Datos a completar</h2>

          <div className="csh-field">
            <label className="csh-label">Dirección exacta</label>
            <input className="csh-input" value={local.direccion} onChange={(e) => setLocal({ ...local, direccion: e.target.value })} />
          </div>

          <div className="csh-row csh-field">
            <div><label className="csh-label">Responsable de contacto *</label><input className="csh-input" value={local.contactoNombre} onChange={(e) => setLocal({ ...local, contactoNombre: e.target.value })} /></div>
            <div><label className="csh-label">Cargo</label><input className="csh-input" value={local.contactoCargo} onChange={(e) => setLocal({ ...local, contactoCargo: e.target.value })} /></div>
          </div>

          <div className="csh-row csh-field">
            <div><label className="csh-label">Teléfono</label><input className="csh-input" value={local.telefono} onChange={(e) => setLocal({ ...local, telefono: e.target.value })} /></div>
            <div><label className="csh-label">Correo electrónico</label><input className="csh-input" type="email" value={local.email} onChange={(e) => setLocal({ ...local, email: e.target.value })} /></div>
          </div>

          <div className="csh-field">
            <label className="csh-label">Horario de atención</label>
            <input className="csh-input" value={local.horarioAtencion} onChange={(e) => setLocal({ ...local, horarioAtencion: e.target.value })} />
          </div>

          <div className="csh-row csh-field">
            <div>
              <label className="csh-label">N° de camas</label>
              <input className="csh-input" type="number" min="0" step="1" value={local.numeroCamas} onChange={(e) => setLocal({ ...local, numeroCamas: e.target.value })} placeholder="Ej. 25" />
            </div>
            <div>
              <label className="csh-label">Tipo de cama</label>
              <select className="csh-select" value={local.tipoCama} onChange={(e) => setLocal({ ...local, tipoCama: e.target.value })}>
                <option value="">Selecciona…</option>
                {TIPOS_CAMA.map((tipo) => <option key={tipo} value={tipo}>{tipo}</option>)}
              </select>
            </div>
          </div>

          <div className="csh-field">
            <label className="csh-label">Cartera de prestaciones ofrecidas *</label>
            <p style={{ fontSize: 12, color: '#6E7268', margin: '0 0 8px' }}>Marca las prestaciones y sub-prestaciones que tu establecimiento ofrece, según el catálogo institucional.</p>
            <PrestacionesPicker value={local.servicios} onChange={(arr) => setLocal({ ...local, servicios: arr })} />
          </div>

          <div className="csh-field">
            <label className="csh-label">Módulo hospitalario SIGCAS</label>
            <SigcasHospitalNav active={sigcasTab} onChange={setSigcasTab} />
            {sigcasTab === 'catalogo' && <><p style={{fontSize:12,color:'#6E7268'}}>Seleccione una prestación del Catálogo Maestro y configure sus campos institucionales.</p><MiCarteraCatalog onSelect={({item})=>setSigcasSelection(item)} />{sigcasSelection && <MiCarteraDynamicForm item={sigcasSelection} onReady={()=>showToast('Configuración validada. Escritura aún deshabilitada en esta fase.')} />}</>}
            {sigcasTab === 'cartera' && <MiCarteraSummary carteraId={null} />}
            {sigcasTab === 'capacidad' && <CapacidadInstaladaPanel readOnly onReady={()=>showToast('Capacidad validada. Escritura aún deshabilitada en esta fase.')} />}
            {sigcasTab === 'documentos' && <div className="csh-card"><strong>Documentos de Gestión</strong><p style={{fontSize:12}}>Plan Anual de Calidad, Plan Médico Funcional, Permiso de Funcionamiento, Planes de Mejora Continua, Licencia Ambiental y Licencia MEER opcional.</p></div>}
          </div>

          <div className="csh-field">
            <label className="csh-label">Observaciones</label>
            <textarea className="csh-textarea" rows={3} value={local.observaciones} onChange={(e) => setLocal({ ...local, observaciones: e.target.value })} />
          </div>

          <button type="submit" className="csh-btn">Guardar perfil</button>
        </form>
      </div>
      {toast && <div className="csh-toast">{toast}</div>}
    </div>
  );
}
